describe("summarizePaymentRequests", () => {
  it("counts only open requests as debt and ignores cancelled/expired money entirely", () => {
    const summary = summarizePaymentRequests([
      request({ id: "1", status: "pending", expectedAmountVnd: 2_400_000 }),
      request({ id: "2", status: "partially_paid", expectedAmountVnd: 2_000_000, paidAmountVnd: 500_000 }),
      request({ id: "3", status: "paid", expectedAmountVnd: 2_600_000, paidAmountVnd: 2_600_000 }),
      request({ id: "4", status: "cancelled", expectedAmountVnd: 9_000_000 }),
      request({ id: "5", status: "expired", expectedAmountVnd: 9_000_000, paidAmountVnd: 100_000 }),
    ]);

    expect(summary.openCount).toBe(2);
    expect(summary.outstandingVnd).toBe(2_400_000 + 1_500_000);
    expect(summary.totalExpectedVnd).toBe(2_400_000 + 2_000_000 + 2_600_000);
    expect(summary.totalPaidVnd).toBe(500_000 + 2_600_000);
    expect(summary.requests).toHaveLength(5);
  });

  it("never reports negative debt for an overpaid open request", () => {
    const summary = summarizePaymentRequests([
      request({ id: "1", status: "partially_paid", expectedAmountVnd: 1_000_000, paidAmountVnd: 1_200_000 }),
    ]);

    expect(summary.outstandingVnd).toBe(0);
    expect(summary.openCount).toBe(1);
  });

  it("returns zeros for a student without requests", () => {
    expect(summarizePaymentRequests([])).toEqual({
      openCount: 0,
      outstandingVnd: 0,
      requests: [],
      totalExpectedVnd: 0,
      totalPaidVnd: 0,
      truncated: false,
    });
  });

  // Value: protects=the summary carries the loader's truncation flag without changing the math; fails_when=the option is dropped or alters totals; why_new=the 200-row window was silent; seam=none; no_claim=does not prove the loader computes the flag (student-activity-data.test)
  it("passes the truncation flag through and keeps totals over the given rows", () => {
    const summary = summarizePaymentRequests([request({ id: "1", status: "pending" })], { truncated: true });

    expect(summary.truncated).toBe(true);
    expect(summary.outstandingVnd).toBe(1_000_000);
  });
});

describe("summarizeAttendance / getAttendanceRate", () => {
  it("counts additional study as attended, rounds the rate, and orders classes by session count", () => {
    const history = summarizeAttendance([
      attendanceItem({ id: "1", status: "present" }),
      attendanceItem({ id: "2", status: "additional_study", classId: "class-8b", className: "Toán 8B" }),
      attendanceItem({ id: "3", status: "unexcused_absence" }),
      attendanceItem({ id: "4", status: "excused_absence", classId: "class-8b", className: "Toán 8B" }),
      attendanceItem({ id: "5", status: "present", classId: "class-8b", className: "Toán 8B" }),
      attendanceItem({ id: "6", status: "present" }),
      attendanceItem({ id: "7", status: "unexcused_absence" }),
    ]);

    expect(history.total).toBe(7);
    expect(history.counts).toEqual({ additional_study: 1, excused_absence: 1, present: 3, unexcused_absence: 2 });
    expect(history.classes.map((klass) => [klass.classId, klass.count])).toEqual([
      ["class-9a", 4],
      ["class-8b", 3],
    ]);
    // 4 attended of 7 = 57.14… → 57, not truncated to 0.57 or inflated by absences.
    expect(getAttendanceRate(history)).toBe(57);
  });

  it("reports no rate (not 0%) when nothing has been marked", () => {
    const history = summarizeAttendance([]);

    expect(history.classes).toEqual([]);
    expect(getAttendanceRate(history)).toBeNull();
    expect(history.truncated).toBe(false);
  });

  // Value: protects=a truncated attendance window is flagged while the rate stays computed over the loaded rows; fails_when=the option is dropped or alters counts; why_new=the 200-row window was silent; seam=none; no_claim=does not prove the loader computes the flag (student-activity-data.test)
  it("passes the truncation flag through without changing counts or the rate", () => {
    const history = summarizeAttendance(
      [attendanceItem({ id: "1", status: "present" }), attendanceItem({ id: "2", status: "unexcused_absence" })],
      { truncated: true },
    );

    expect(history.truncated).toBe(true);
    expect(history.total).toBe(2);
    expect(getAttendanceRate(history)).toBe(50);
  });
});

describe("buildStudentHistory", () => {
  const classInfo = { code: "L-9A", defaultLearningMode: "offline", grade: 9, id: "class-9a", level: "A" as const, name: "Toán 9A", status: "active" };
  const enrollmentHistory = [
    { classInfo, effectiveFrom: "2026-09-01", effectiveTo: null, endReason: null, id: "enr-2", registeredMode: "offline" as const, startReason: null, status: "active", transitionKind: "transfer" },
    { classInfo: null, effectiveFrom: "2025-09-01", effectiveTo: "2026-08-31", endReason: "Lên lớp", id: "enr-1", registeredMode: "online" as const, startReason: "Đăng ký mới", status: "completed", transitionKind: "initial" },
  ];
  const tuitionProfile = {
    currentRateVnd: 200_000,
    rateHistory: [{ createdAt: "2026-01-02T00:00:00Z", effectiveFrom: "2026-01-01", reason: "Tăng giá", unitPriceVnd: 200_000 }],
    sourceHistory: [{ assignedAt: "2025-08-15", reason: "Giới thiệu" }],
    sourceName: "Giới thiệu",
    sources: [],
  };

  it("merges enrollment, rate and source events newest-first with end events only for ended enrollments", () => {
    const events = buildStudentHistory({ canViewClasses: true, enrollmentHistory, tuitionProfile });

    expect(events.map((event) => [event.date, event.title])).toEqual([
      ["2026-09-01", "Chuyển lớp · Toán 9A · Tại lớp"],
      ["2026-08-31", "Kết thúc lớp không xác định"],
      ["2026-01-01", `Mức phí ${formatVnd(200_000)}/buổi có hiệu lực`],
      ["2025-09-01", "Nhập lớp ban đầu · lớp không xác định · Trực tuyến"],
      ["2025-08-15", "Hiệu chỉnh nguồn học viên"],
    ]);
    expect(events.find((event) => event.id === "enr-1-end")?.detail).toBe("Lên lớp");
    expect(events.find((event) => event.id === "enr-1-start")?.detail).toBe("Đăng ký mới");
  });

  it("drops enrollment events without classes.view but keeps tuition events", () => {
    const events = buildStudentHistory({ canViewClasses: false, enrollmentHistory, tuitionProfile });

    expect(events.map((event) => event.title)).toEqual([
      `Mức phí ${formatVnd(200_000)}/buổi có hiệu lực`,
      "Hiệu chỉnh nguồn học viên",
    ]);
  });

  it("is empty when there is nothing to show", () => {
    expect(buildStudentHistory({ canViewClasses: true, enrollmentHistory: [], tuitionProfile: null })).toEqual([]);
  });
});
